<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientSubjectTypeOptions;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientSubjectTypeAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientSubjectTypeAccessor trait.
 *
 * Covers null default, string/VO assignment via withSubjectType,
 * getSubjectType/subjectType accessors, and isSubjectTypeChanged with/without original.
 */
class TrustedClientSubjectTypeAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSubjectType creates a new instance with the SubjectType set
     * from a string value, and getSubjectType returns the primitive string.
     */
    public function testWithSubjectTypeFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientSubjectTypeAccessorUnitTest();

        // Act
        $result = $holder->withSubjectType(TrustedClientSubjectTypeOptions::PUBLIC);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TrustedClientSubjectTypeOptions::PUBLIC, $result->getSubjectType());
    }
    /**
     * Asserts that withsubjectType has access to the value object
     * from a string value, and getSubjectType returns the primitive string.
     */
    public function testWithSubjectTypeFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientSubjectTypeAccessorUnitTest();

        // Act
        $result = $holder->withSubjectType(TrustedClientSubjectTypeOptions::PUBLIC);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TrustedClientSubjectTypeOptions::PUBLIC, $result->subjectType()->value());
    }
    public function testChangedSubjectType(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientSubjectTypeAccessorUnitTest()->withSubjectType(TrustedClientSubjectTypeOptions::PUBLIC);
        $original = $holder->withSubjectType(TrustedClientSubjectTypeOptions::PUBLIC);
        $same = $holder->withSubjectType(TrustedClientSubjectTypeOptions::PUBLIC);
        $modified = $holder->withSubjectType(TrustedClientSubjectTypeOptions::PAIRWISE);

        // Act
        $withSame = $original->isSubjectTypeChanged($same);
        $withDiferent = $original->isSubjectTypeChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientSubjectTypeAccessorUnitTest
{
    use TrustedClientSubjectTypeAccessor;
}
